//! Platform-neutral key event types.

/// State carried by an evdev `EV_KEY` event.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum KeyValue {
    Up,
    Down,
    /// Auto-repeat generated by the Linux input layer while a key is held.
    Repeat,
}

impl KeyValue {
    pub fn from_evdev(value: i32) -> Option<Self> {
        match value {
            0 => Some(Self::Up),
            1 => Some(Self::Down),
            2 => Some(Self::Repeat),
            _ => None,
        }
    }

    pub fn as_u8(self) -> u8 {
        match self {
            Self::Up => 0,
            Self::Down => 1,
            Self::Repeat => 2,
        }
    }

    pub fn from_u8(v: u8) -> Option<Self> {
        Self::from_evdev(v as i32)
    }
}

/// A key event identified by its Linux evdev key code (`KEY_*` in
/// `linux/input-event-codes.h`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct KeyEvent {
    pub code: u16,
    pub value: KeyValue,
}
